from pathlib import Path

root = Path('.')
plan_path = root / 'src/main/java/LicenseRecoverModernGUIJavaPlan.java'
test_path = root / 'src/test/java/RefactorSmokeTest.java'

plan = plan_path.read_text(encoding='utf-8')
old = '''        File jar = findRegJar(lib);\n        boolean packed = jar != null && isVirboxPackedJar(jar);\n        String products = directoryMapping != null ? directoryMapping.productMainNum\n                : resolveRegStr(root, runtimeProduct, lib);\n\n        String recoveredLocalRegStr = blank(runtimeProduct)\n                ? null : ExistingLocalRegStrProbe.recover(root, lib, runtimeProduct);\n        boolean binaryIdentity = !blank(binaryFamily)\n                && (!blank(binaryRuntime) || !blank(configDrivenRuntime));\n        boolean directoryIdentity = directoryMapping != null\n                || directDataIdentity || !blank(confirmedClassesFamily) || binaryIdentity;\n        boolean directoryRegStr = directoryMapping != null\n                || dataRegInfo != null || classesRegInfo != null || recoveredLocalRegStr != null;\n'''
new = '''        File jar = findRegJar(lib);\n        boolean packed = jar != null && isVirboxPackedJar(jar);\n        String configDrivenPrimaryRegStr = confirmedConfigDrivenPrimaryRegStr(\n                root, soft, family, configDrivenRuntime);\n        String recoveredLocalRegStr = null;\n        String products;\n        if (directoryMapping != null) {\n            products = directoryMapping.productMainNum;\n        } else if (dataRegInfo != null) {\n            products = dataRegInfo;\n        } else if (classesRegInfo != null) {\n            products = classesRegInfo;\n        } else if (!blank(configDrivenPrimaryRegStr)) {\n            products = configDrivenPrimaryRegStr;\n        } else {\n            recoveredLocalRegStr = blank(runtimeProduct)\n                    ? null : ExistingLocalRegStrProbe.recover(root, lib, runtimeProduct);\n            products = recoveredLocalRegStr;\n        }\n\n        boolean binaryIdentity = !blank(binaryFamily)\n                && (!blank(binaryRuntime) || !blank(configDrivenRuntime));\n        boolean directoryIdentity = directoryMapping != null\n                || directDataIdentity || !blank(confirmedClassesFamily) || binaryIdentity;\n        boolean directoryRegStr = directoryMapping != null\n                || dataRegInfo != null || classesRegInfo != null\n                || !blank(configDrivenPrimaryRegStr) || recoveredLocalRegStr != null;\n'''
if old not in plan:
    raise SystemExit('products block anchor not found')
plan = plan.replace(old, new, 1)

anchor = '''    static boolean confirmedProductAllNumRuntimeProduct(File classes) {\n'''
method = '''    /**\n     * Confirm that the selected application's own primary registration path requires\n     * the concrete VersionID to occur in RegInfo.RegStr.  This is deliberately stronger\n     * than runtime ProductID proof: systemConfig.yml, classes/config.xml, SystemInfo,\n     * RegisterContant and RegisterListener must all agree before the concrete id is used\n     * as a static RegStr.  Compatibility/alternate-platform checks are not used here.\n     */\n    static String confirmedConfigDrivenPrimaryRegStr(File root, String softId,\n                                                      String confirmedFamily,\n                                                      String confirmedRuntimeProduct) {\n        if (root == null || blank(softId) || blank(confirmedFamily)\n                || blank(confirmedRuntimeProduct)) return null;\n        String concrete = softId.trim();\n        String family = confirmedFamily.trim();\n        String runtime = confirmedRuntimeProduct.trim();\n        if (!concrete.equalsIgnoreCase(runtime)) return null;\n        if (!concrete.toUpperCase(Locale.ROOT).startsWith(family.toUpperCase(Locale.ROOT))) return null;\n\n        String ymlVersion = readSystemConfigVersionId(root);\n        if (blank(ymlVersion) || !concrete.equalsIgnoreCase(ymlVersion.trim())) return null;\n\n        File classes = new File(root, "WEB-INF" + File.separator + "classes");\n        File config = new File(classes, "config.xml");\n        String configured = readElement(config, "SoftVersionID");\n        if (blank(configured) || !concrete.equalsIgnoreCase(configured.trim())) return null;\n\n        File systemInfo = new File(classes, "com" + File.separator + "itmc" + File.separator\n                + "register" + File.separator + "utils" + File.separator + "SystemInfo.class");\n        File registerContant = new File(classes, "com" + File.separator + "itmc" + File.separator\n                + "register" + File.separator + "utils" + File.separator + "RegisterContant.class");\n        File listener = new File(classes, "com" + File.separator + "itmc" + File.separator\n                + "register" + File.separator + "service" + File.separator + "RegisterListener.class");\n\n        if (!classFileContainsAll(systemInfo, "config.xml", "SystemSoft", "registerId")) return null;\n        if (!classFileContainsAll(registerContant, "global.system.VersionID", "versionID",\n                "java/util/Properties", "getProperty")) return null;\n        if (!classFileContainsAll(listener, "com/itmc/register/utils/SystemInfo", "registerId",\n                "itmc/regedit/RegisterMain", "getRegStr",\n                "com/itmc/register/utils/RegisterContant", "versionID", "contains")) return null;\n        return concrete;\n    }\n\n    private static String readSystemConfigVersionId(File root) {\n        if (root == null) return null;\n        File yml = new File(root, "systemConfig.yml");\n        if (!yml.isFile()) return null;\n        try {\n            for (String raw : Files.readAllLines(yml.toPath(), StandardCharsets.UTF_8)) {\n                String line = raw.trim();\n                if (!line.toLowerCase(Locale.ROOT).contains("versionid")) continue;\n                int split = line.indexOf(':');\n                if (split < 0) split = line.indexOf('=');\n                if (split > 0) {\n                    String value = line.substring(split + 1).trim();\n                    if (!value.isEmpty()) return value;\n                }\n            }\n        } catch (Exception ignore) { }\n        return null;\n    }\n\n'''
if anchor not in plan:
    raise SystemExit('method insertion anchor not found')
plan = plan.replace(anchor, method + anchor, 1)
plan_path.write_text(plan, encoding='utf-8')

test = test_path.read_text(encoding='utf-8')
old_cfg = '''        Files.write(ds501Classes.resolve("config.xml"), Arrays.asList(\n                "<ROOT><reg><regType>3</regType></reg><SystemSoft><SoftVersionID>DS50109</SoftVersionID></SystemSoft></ROOT>"), StandardCharsets.UTF_8);\n'''
new_cfg = old_cfg + '''        Files.write(ds501Root.resolve("systemConfig.yml"),\n                Arrays.asList("global.system.VersionID=DS50109"), StandardCharsets.UTF_8);\n'''
if old_cfg not in test:
    raise SystemExit('DS50109 config anchor not found')
test = test.replace(old_cfg, new_cfg, 1)

old_evidence = '''        Path ds501SystemInfo = ds501Classes.resolve("com/itmc/register/utils/SystemInfo.class");\n        Path ds501Listener = ds501Classes.resolve("com/itmc/register/service/RegisterListener.class");\n        Files.createDirectories(ds501SystemInfo.getParent());\n        Files.createDirectories(ds501Listener.getParent());\n        Files.write(ds501SystemInfo,\n                "config.xml SystemSoft registerId".getBytes(StandardCharsets.US_ASCII));\n        Files.write(ds501Listener,\n                "com/itmc/register/utils/SystemInfo registerId itmc/regedit/RegisterMain getRegStr versionID contains"\n                        .getBytes(StandardCharsets.US_ASCII));\n        ds501Plan = LicenseRecoverModernGUIJavaPlan.inspect(ds501Root.toFile());\n        check("DS501".equals(ds501Plan.authorizationFamily)\n                        && "DS50109".equals(ds501Plan.runtimeProductId)\n                        && ds501Plan.automaticRecoveryReady\n                        && ds501Plan.regStrSummary().contains("动态"),\n                "DS501 concrete runtime ID is accepted from target config only when target bytecode proves config->RegisterMain flow");\n'''
new_evidence = '''        Path ds501SystemInfo = ds501Classes.resolve("com/itmc/register/utils/SystemInfo.class");\n        Path ds501Contant = ds501Classes.resolve("com/itmc/register/utils/RegisterContant.class");\n        Path ds501Listener = ds501Classes.resolve("com/itmc/register/service/RegisterListener.class");\n        Files.createDirectories(ds501SystemInfo.getParent());\n        Files.createDirectories(ds501Listener.getParent());\n        Files.write(ds501SystemInfo,\n                "config.xml SystemSoft registerId".getBytes(StandardCharsets.US_ASCII));\n        Files.write(ds501Contant,\n                "global.system.VersionID versionID java/util/Properties getProperty"\n                        .getBytes(StandardCharsets.US_ASCII));\n        Files.write(ds501Listener,\n                "com/itmc/register/utils/SystemInfo registerId itmc/regedit/RegisterMain getRegStr "\n                        .concat("com/itmc/register/utils/RegisterContant versionID contains")\n                        .getBytes(StandardCharsets.US_ASCII));\n        ds501Plan = LicenseRecoverModernGUIJavaPlan.inspect(ds501Root.toFile());\n        check("DS501".equals(ds501Plan.authorizationFamily)\n                        && "DS50109".equals(ds501Plan.runtimeProductId)\n                        && "DS50109".equals(ds501Plan.regStr)\n                        && ds501Plan.automaticRecoveryReady\n                        && !ds501Plan.regStrSummary().contains("动态"),\n                "DS50109 derives primary RegStr statically only from target VersionID->registerId->RegisterMain->RegStr.contains(versionID) flow");\n\n        Path ds501WeakRoot = base.resolve("java-DS50112-weak-primary-regstr");\n        Path ds501WeakLib = ds501WeakRoot.resolve("WEB-INF/lib");\n        Path ds501WeakClasses = ds501WeakRoot.resolve("WEB-INF/classes");\n        Files.createDirectories(ds501WeakLib);\n        Files.createDirectories(ds501WeakClasses.resolve("com/itmc/register/utils"));\n        Files.createDirectories(ds501WeakClasses.resolve("com/itmc/register/service"));\n        Files.write(ds501WeakLib.resolve("ITMCReg.jar"), new byte[]{1});\n        Files.write(ds501WeakRoot.resolve("systemConfig.yml"),\n                Arrays.asList("global.system.VersionID=DS50112"), StandardCharsets.UTF_8);\n        Files.write(ds501WeakClasses.resolve("config.xml"), Arrays.asList(\n                "<ROOT><SystemSoft><SoftVersionID>DS50112</SoftVersionID></SystemSoft></ROOT>"), StandardCharsets.UTF_8);\n        Files.write(ds501WeakClasses.resolve("RegistrationEvidence.class"),\n                "DS501".getBytes(StandardCharsets.US_ASCII));\n        Files.write(ds501WeakClasses.resolve("com/itmc/register/utils/SystemInfo.class"),\n                "config.xml SystemSoft registerId".getBytes(StandardCharsets.US_ASCII));\n        Files.write(ds501WeakClasses.resolve("com/itmc/register/service/RegisterListener.class"),\n                "com/itmc/register/utils/SystemInfo registerId itmc/regedit/RegisterMain getRegStr "\n                        .concat("com/itmc/register/utils/RegisterContant versionID contains")\n                        .getBytes(StandardCharsets.US_ASCII));\n        LicenseRecoverModernGUIJavaPlan ds501WeakPlan =\n                LicenseRecoverModernGUIJavaPlan.inspect(ds501WeakRoot.toFile());\n        check("DS50112".equals(ds501WeakPlan.runtimeProductId)\n                        && ds501WeakPlan.regStr == null\n                        && ds501WeakPlan.regStrSummary().contains("动态")\n                        && ds501WeakPlan.automaticRecoveryReady,\n                "DS501 runtime proof alone does not synthesize static RegStr when RegisterContant VersionID source proof is missing");\n\n        Path ds50113Root = base.resolve("java-DS50113");\n        Path ds50113Lib = ds50113Root.resolve("WEB-INF/lib");\n        Path ds50113Classes = ds50113Root.resolve("WEB-INF/classes");\n        Files.createDirectories(ds50113Lib);\n        Files.createDirectories(ds50113Classes.resolve("com/itmc/register/utils"));\n        Files.createDirectories(ds50113Classes.resolve("com/itmc/register/service"));\n        Files.write(ds50113Lib.resolve("ITMCReg.jar"), new byte[]{1});\n        Files.write(ds50113Root.resolve("systemConfig.yml"),\n                Arrays.asList("global.system.VersionID=DS50113"), StandardCharsets.UTF_8);\n        Files.write(ds50113Classes.resolve("config.xml"), Arrays.asList(\n                "<ROOT><SystemSoft><SoftVersionID>DS50113</SoftVersionID></SystemSoft></ROOT>"), StandardCharsets.UTF_8);\n        Files.write(ds50113Classes.resolve("RegistrationEvidence.class"),\n                "DS501".getBytes(StandardCharsets.US_ASCII));\n        Files.write(ds50113Classes.resolve("com/itmc/register/utils/SystemInfo.class"),\n                "config.xml SystemSoft registerId".getBytes(StandardCharsets.US_ASCII));\n        Files.write(ds50113Classes.resolve("com/itmc/register/utils/RegisterContant.class"),\n                "global.system.VersionID versionID java/util/Properties getProperty"\n                        .getBytes(StandardCharsets.US_ASCII));\n        Files.write(ds50113Classes.resolve("com/itmc/register/service/RegisterListener.class"),\n                "com/itmc/register/utils/SystemInfo registerId itmc/regedit/RegisterMain getRegStr "\n                        .concat("com/itmc/register/utils/RegisterContant versionID contains")\n                        .getBytes(StandardCharsets.US_ASCII));\n        LicenseRecoverModernGUIJavaPlan ds50113Plan =\n                LicenseRecoverModernGUIJavaPlan.inspect(ds50113Root.toFile());\n        check("DS501".equals(ds50113Plan.authorizationFamily)\n                        && "DS50113".equals(ds50113Plan.runtimeProductId)\n                        && "DS50113".equals(ds50113Plan.regStr)\n                        && ds50113Plan.automaticRecoveryReady,\n                "DS50113 independently proves concrete primary RegStr from its own target-directory registration flow");\n'''
if old_evidence not in test:
    raise SystemExit('DS501 evidence block anchor not found')
test = test.replace(old_evidence, new_evidence, 1)
test_path.write_text(test, encoding='utf-8')

(root / 'VERSION.txt').write_text('1.2.22\n', encoding='utf-8')
readme = (root / 'README.md').read_text(encoding='utf-8')
needle = '当前稳定版本：**v1.2.21**'
if needle not in readme:
    raise SystemExit('README version anchor not found')
readme = readme.replace(needle, '当前稳定版本：**v1.2.22**', 1)
(root / 'README.md').write_text(readme, encoding='utf-8')

notes = '''# LicenseRecover v1.2.22\n\n本版根据真实 DS50109 与 DS50113 目标目录进一步收紧 Java DS501/classes-config 的 RegStr 证据链，减少不必要的目标 `RegisterMain.getRegInfo()` 动态读取。\n\n- **DS501 主 RegStr 可纯静态确认**：只有目标目录同时证明 `systemConfig.yml VersionID = classes/config.xml SoftVersionID`、`SystemInfo` 从 `config.xml/SystemSoft` 写入 `registerId`、`RegisterContant` 从 `global.system.VersionID` 写入/持有 `versionID`，并且 `RegisterListener` 使用 `RegisterMain(registerId).getRegInfo().getRegStr().contains(versionID)` 时，才把当前具体 VersionID 作为主 RegStr。\n- **真实样本结果**：DS50109 现在可静态得到 `AuthorizationFamily=DS501 / RuntimeProductID=DS50109 / RegStr=DS50109`；DS50113 同理得到 `DS501 / DS50113 / DS50113`。\n- **兼容授权不覆盖主身份**：DS50113 中的 `QT1001 / QT100112` 等替代平台检查仍只视为兼容链，不会覆盖当前 DS50113 的主 RegStr。\n- **Fail-closed 保持**：缺少 `systemConfig.yml`、RegisterContant VersionID 来源证明、RegisterListener membership 检查或任一关键目标证据时，不会从 `DS501xx` 命名规则猜 RegStr；若运行 ProductID 已有充分证据且目标 ITMCReg 可用，则仍保留“目标组件动态读取”，否则阻止自动恢复。\n- **减少动态加载**：静态证据完整的 DS501 应用在批量扫描阶段不再为了 RegStr 调用目标注册组件，扫描更快，也进一步减少执行厂商注册代码的次数。\n- **PRE-BLOCK FIRST 不变**：v1.2.21 的 Java/.NET 首次 Patch 前授权网络隔离仍完整保留。\n'''
(root / 'release-notes/v1.2.22.md').write_text(notes, encoding='utf-8')

print('patched DS501 static RegStr evidence and prepared v1.2.22')
